const raw = $input.item.json.output || '';
let parsed = { major_issue: false, score: 0, review_summary: '', major_issue_reason: '' };
try {
  const clean = raw.replace(/^```json\s*/m, '').replace(/```\s*$/m, '');
  const obj = JSON.parse(clean);
  parsed = { ...parsed, ...obj };
} catch(e) {
  parsed.major_issue = raw.includes('"major_issue": true') || raw.includes('"major_issue":true');
}
return [{ json: {
  major_issue: parsed.major_issue === true,
  score: Number(parsed.score) || 0,
  review_summary: String(parsed.review_summary || ''),
  major_issue_reason: String(parsed.major_issue_reason || ''),
  review_output: raw
}}];

